mapper.select:
select a.id, a.cell_sha256_code_list, a.package_id ,d.priority from b_xiecheng_colliding_data_rob a join (${queryRuleScoreDataSql}) AS b on a.cell_sha256_code_list = b.cell join b_xiecheng_colliding_data_package d on a.package_id = d.id left join b_xiecheng_colliding_data_loop_cycle c on a.cell_sha256_code_list = c.cell_sha256_code_list and c.is_delete = 0 where c.id is null and a.is_delete = 0 and d.is_delete = 0
and a.id > #{minId}
order by a.id limit 2000;

SELECT id, cell FROM (SELECT a.id,a.cell, ROW_NUMBER() OVER (PARTITION BY a.cell ORDER BY a.id) AS row_num FROM (${queryRuleScoreDataSql}) AS a LEFT JOIN b_xiecheng_colliding_data_loop_cycle AS b ON a.cell = b.cell_sha256_code_list AND b.is_delete = 0 LEFT JOIN b_xiecheng_colliding_data_rob AS c ON a.cell = c.cell_sha256_code_list and c.is_delete = 0 WHERE b.id IS NULL AND c.id IS NULL) AS t WHERE row_num = 1
and t.id > #{minId}
order by t.id LIMIT 2000;
